      out.write("        \r\n");
      out.write("        // Lấy giá trị radio gender đang chọn\r\n");
      out.write("        const genderRadio = document.querySelector(\".filter-gender:checked\");\r\n");
      out.write("        const selectedGender = genderRadio ? genderRadio.value : \"all\";\r\n");
      out.write("\r\n");
      out.write("        products.forEach((product) => {\r\n");
      out.write("            const pType = product.getAttribute(\"data-type\");\r\n");
      out.write("            const pGender = product.getAttribute(\"data-gender\");\r\n");
      out.write("            const pPrice = parseFloat(product.getAttribute(\"data-price\"));\r\n");
      out.write("\r\n");
      out.write("            // Logic kiểm tra Loại (Nếu không chọn cái nào thì hiện tất cả)\r\n");
