      out.write("\r\n");
      out.write("            // Logic kiểm tra Giới tính\r\n");
      out.write("            const genderMatch = selectedGender === \"all\" || pGender === selectedGender;\r\n");
      out.write("\r\n");
      out.write("            // Logic kiểm tra Giá\r\n");
      out.write("            let priceMatch = selectedPrices.length === 0;\r\n");
      out.write("            selectedPrices.forEach(range => {\r\n");
      out.write("                const [min, max] = range.split(\"-\").map(Number);\r\n");
      out.write("                if (pPrice >= min && pPrice <= max) priceMatch = true;\r\n");
      out.write("            });\r\n");
      out.write("\r\n");
      out.write("            // HIỂN THỊ: Sản phẩm phải khớp TẤT CẢ các điều kiện (AND)\r\n");
      out.write("            if (typeMatch && genderMatch && priceMatch) {\r\n");
      out.write("                product.style.display = \"\"; \r\n");
      out.write("            } else {\r\n");
      out.write("                product.style.display = \"none\";\r\n");
      out.write("            }\r\n");
      out.write("        });\r\n");
